SELECT watch_min / 60.0 AS total_watch_hours
FROM ads_platform_daily
WHERE day_index = 12;

SELECT COUNT(*) AS users_first_observed_on_day_0
FROM dim_user
WHERE first_day = 0;

WITH user_stats AS (
  SELECT n_streamers_watched
  FROM dim_user
)
SELECT AVG(n_streamers_watched)::DOUBLE AS avg_streamers_watched_per_user
FROM user_stats;

SELECT watch_min / 60.0 AS watch_time_hours
FROM ads_platform_daily
WHERE day_index = 12;

SELECT COUNT(*) AS users_first_observed_day_0
FROM dim_user
WHERE first_day = 0;

SELECT AVG(retention_d7) AS avg_retention_d7
FROM ads_user_retention
WHERE retention_d7 IS NOT NULL;

SELECT total_watch_min
FROM dim_streamer
WHERE streamer = 'tfue';

SELECT watch_min / 60.0 AS total_watch_time_hours
FROM ads_platform_daily
WHERE day_index = 12;

SELECT COUNT(*) as users_first_observed_day_0
FROM dim_user
WHERE first_day = 0;

WITH user_stats AS (
  SELECT n_streamers_watched
  FROM dim_user
)
SELECT AVG(n_streamers_watched)
FROM user_stats;
